// https://github.com/twbs/bootstrap/blob/v5.3.8/scss/_variables.scss

// Brand
$primary: #002288;
$secondary: #475567;

// Typography
$font-family-base: "Roboto", sans-serif;
$font-family-sans-serif: "Roboto", sans-serif;
$small-font-size: 0.9rem;

// Header / Footer
$header-background-color: #fff;
$header-color: invert($header-background-color) !default;

$footer-background-color: #eef2f7;
$footer-color: $secondary;

$font-weight-normal: 400;
$font-weight-medium: 500;
$font-weight-bold: 600;

$hero-background-color: $header-background-color !default;
$hero-color: $header-color !default;
$hero-h1-font-size: $h1-font-size !default;

$font-size-base: 1.3rem !default; // Assumes the browser default, typically `16px`

$h1-font-size:                $font-size-base * 2.5 !default;
$h2-font-size:                $font-size-base * 2 !default;
$h3-font-size:                $font-size-base * 1.75 !default;
$h4-font-size:                $font-size-base * 1.5 !default;
$h5-font-size:                $font-size-base * 1.25 !default;
$h6-font-size:                $font-size-base !default;
// scss-docs-end font-variables


$legend-font-size:            1.5rem !default;
