// https://github.com/twbs/bootstrap/blob/v5.3.2/scss/_variables.scss

$primary: #335eea;
$secondary: #3d5480;
$black: #161c2d;
$gray: #869ab8;
$gray-dark: #384c74;
$gray-100: #f9fbfd;
$gray-200: #f1f4f8;
$gray-300: #d9e2ef;
$gray-400: #c6d3e6;
$gray-500: #abbcd5;
$gray-600: #869ab8;
$gray-700: #506690;
$gray-800: #384c74;
$gray-900: #1b2a4e;
$success: #42ba96;
$info: #6a55e1;
$warning: #fad776;
$danger: #d52f43;
$light: $gray-200;
$dark: $gray-900;


// Alert
$alert-link-font-weight: normal;

// Border
$border-radius: 0.375rem;
$border-radius-sm: 0.25rem;
$border-radius-lg: 0.5rem;
$border-radius-xl: 1rem;
$border-radius-xxl: 2rem;
$border-color: $gray-200;

// Breadcrumb
$breadcrumb-font-size: .75rem;
$breadcrumb-margin-bottom: 0;
$breadcrumb-padding-y: px2rem(10);
$breadcrumb-divider-color: rgba($secondary, .9);
$breadcrumb-item-active-color: $secondary;

// Buttons
$btn-close-opacity: 1;
$btn-font-size: 1.0625rem;
$btn-font-weight: 600;
$btn-line-height: 1.6;
$btn-padding-y: 0.8125rem;
$btn-padding-x: 1.25rem;

// Font
$font-family-sans-serif: "Hanken Grotesk", sans-serif;
$font-weight-bold: 600;
$headings-line-height: 1.1;
$headings-margin-bottom: 1rem;
$h1-font-size: 2.5rem;
// $h2-font-size: 2rem
$lead-font-size: px2rem(19);
$small-font-size: .875rem;
$line-height-base: 1.6;

$hr-margin-y: 2.8rem;

// Nav
$nav-link-font-size: 1.0625rem;
$nav-link-font-weight: 600;
$nav-link-padding-y: .625rem;
$navbar-padding-y: 1rem;

// Pagination
$pagination-border-radius: 50%;
$pagination-padding-y: .5rem;
$pagination-padding-x: .75rem;
$pagination-disabled-bg: transparent;
$pagination-color: $primary;
$pagination-bg: white;
$pagination-focus-color: $primary;
$pagination-focus-box-shadow: 0 0 0 0.25rem rgba($pagination-bg, 0.25);
$pagination-active-color: $pagination-bg;
$pagination-active-bg: $pagination-color;
$pagination-active-border-color: $pagination-color;
$pagination-hover-color: $pagination-active-color;
$pagination-hover-bg: $pagination-active-bg;
$pagination-hover-border-color: $pagination-active-bg;

// Spacing
$spacer: 1.25rem;

// Hugolify
$header-height: 80px;
$header-background-color: white;
$header-color: $black;
$footer-background-color: #E7ECFF;
$footer-color: $secondary;
$global-spacing: 5rem;
$global-spacing-double: 10rem;
