.home-page {
    .hero {
        .container {
            min-height: $home-hero-min-height-mobile;
            @include media-breakpoint-up(md) {
                min-height: $home-hero-min-height; } }
        h1 {
            @include font-size($home-hero-h1-font-size); } }
    .latest {
        @include margin-bottom($global-spacing);
        @include margin-top($global-spacing); } }
