.transcription {
    details {
        background: transparent;
        border: 0;
        border-radius: 0;
        @media (hover: hover) and (pointer: fine) {
            &:hover {
                box-shadow: none; } }
        summary {
            font-size: 1rem;
            padding: .5rem 2rem .5rem .5rem;
            text-align: right;
            &::after {
                font-size: 1rem;
                right: 0.5rem;
                top: 0.5rem; } }
        p {
            font-size: 1rem; } } }
