// Semantic column classes — dynamic ratio mapping
// Ratios: xsmall=1/3, small=1/2, medium=2/3, large=5/6
// Adapts to any $grid-columns value (default: 12)
// in variables.default.sass:
// $semantic-cols: ("xsmall": (1, 3), "small": (1, 2), "medium": (2, 3), "large": (5, 6))

@each $name, $ratio in $semantic-cols {
    $num: nth($ratio, 1);
    $den: nth($ratio, 2);
    .col-#{$name} {
        @include media-breakpoint-up(md) {
            @include make-col(round(divide($grid-columns * $num, $den))); } } }

// Semantic offset classes
.offset-center {
    @include media-breakpoint-up(md) {
        margin-left: auto;
        margin-right: auto; } }

.offset-end {
    @include media-breakpoint-up(md) {
        margin-left: auto; } }
