.categories {
    --bs-gutter-y: calc(#{$global-spacing} / 2);
    @extend .row;
    @extend .row-cols-2;
    @extend .row-cols-md-3;
    @extend .row-cols-lg-4;
    @include media-breakpoint-up(md) {
        --bs-gutter-y: #{$grid-gutter-width}; }
    & + nav {
        @include margin-top($global-spacing); } }
